'use strict';
let kioskAdmin={templates:[],menu:[],selected:0};
const kioskEscape=value=>{const node=document.createElement('span');node.textContent=value??'';return node.innerHTML};
const kioskActive=value=>Number(value)?'<span class="badge green">เปิด</span>':'<span class="badge">ปิด</span>';
async function kioskApiGet(action,params={}){const query=new URLSearchParams({action,...params});const response=await fetch(`${KQ_API}?${query}`,{credentials:'same-origin'});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่สามารถโหลดข้อมูล Kiosk ได้');return body}
async function renderKioskAdmin(){
  const [templates,buildings,departments,services]=await Promise.all([kqApi('kiosk-templates'),kqApi('buildings'),kqApi('departments'),kqApi('services')]);
  kioskAdmin.templates=templates.data;kioskAdmin.buildings=buildings.data;kioskAdmin.departments=departments.data;kioskAdmin.services=services.data;
  document.getElementById('pageTitle').textContent='จุดบริการ Kiosk';
  document.getElementById('viewContent').innerHTML=`<div class="page-card"><div class="page-toolbar"><div><h2>จุดบริการ Kiosk</h2><p>สร้างจุดติดตั้งแยกจากสาขา แล้วกำหนดอาคาร ตำแหน่ง และชุดปุ่มประจำจุด</p></div><button class="primary" id="addKioskTemplate">＋ เพิ่มจุดบริการ Kiosk</button></div>${simpleTable(['รหัส','จุดบริการ','อาคาร','ตำแหน่งติดตั้ง','ปุ่ม','ลิงก์หน้าจอ','สถานะ',''],kioskAdmin.templates.map(k=>[kioskEscape(k.code),kioskEscape(k.name),kioskEscape(k.building_name),kioskEscape(k.location_label||'-'),`${k.menu_count} ปุ่ม`,`<a class="kiosk-link" href="kiosk.html?kiosk=${encodeURIComponent(k.code)}" target="_blank">kiosk.html?kiosk=${kioskEscape(k.code)}</a>`,kioskActive(k.active),`<div class="action-cell"><button class="record-button" data-kiosk-menu="${k.id}">จัดการปุ่ม</button><button class="record-button" data-kiosk-edit="${k.id}">แก้ไข</button><a class="record-button" href="kiosk.html?kiosk=${encodeURIComponent(k.code)}" target="_blank">เปิดหน้าจอ</a></div>`]),kioskAdmin.templates)}<div id="kioskMenuArea"></div></div>`;
  document.getElementById('addKioskTemplate').onclick=()=>openKioskTemplateDialog();
  document.querySelectorAll('[data-kiosk-edit]').forEach(b=>b.onclick=()=>openKioskTemplateDialog(kioskAdmin.templates.find(x=>String(x.id)===b.dataset.kioskEdit)));
  document.querySelectorAll('[data-kiosk-menu]').forEach(b=>b.onclick=()=>renderKioskMenu(+b.dataset.kioskMenu));
}
function kioskDialog(title,fields,onSubmit){const wrap=document.createElement('div');wrap.className='crud-backdrop';wrap.innerHTML=`<form class="crud-dialog"><header><div><span class="eyebrow">KIOSK SETTING</span><h2>${title}</h2></div><button type="button" class="icon-button" data-close>×</button></header><div class="crud-form-grid">${fields}<label class="toggle-label full"><input name="active" type="checkbox" checked> เปิดใช้งาน</label></div><div class="auth-error hidden" data-error></div><div class="dialog-actions"><button type="button" class="secondary" data-close>ยกเลิก</button><button class="primary">บันทึก</button></div></form>`;document.body.append(wrap);wrap.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>wrap.remove());wrap.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await onSubmit(e.currentTarget);wrap.remove();const selected=kioskAdmin.selected;await renderKioskAdmin();if(selected)await renderKioskMenu(selected)}catch(error){const box=wrap.querySelector('[data-error]');box.textContent=error.message;box.classList.remove('hidden')}};return wrap}
function openKioskTemplateDialog(record={}){const edit=!!record.id;const fields=`<input type="hidden" name="id" value="${record.id||0}"><label>อาคาร<select name="building_id" required>${kioskAdmin.buildings.map(x=>`<option value="${x.id}" ${String(x.id)===String(record.building_id)?'selected':''}>${kioskEscape(x.name)}</option>`).join('')}</select></label><label>รหัสจุดบริการ<input name="code" value="${kioskEscape(record.code||'')}" required pattern="[A-Za-z0-9_-]{2,40}" placeholder="เช่น ER"></label><label>ชื่อจุดบริการ Kiosk<input name="name" value="${kioskEscape(record.name||'')}" required placeholder="Kiosk อาคาร ER"></label><label>ตำแหน่งติดตั้ง<input name="location_label" value="${kioskEscape(record.location_label||'')}" placeholder="เช่น ทางเข้า ER ชั้น 1"></label><div class="kiosk-dialog-note">ลิงก์ใช้งานจะเป็น kiosk.html?kiosk=รหัส เช่น kiosk.html?kiosk=ER</div>`;const wrap=kioskDialog(edit?'แก้ไขจุดบริการ Kiosk':'เพิ่มจุดบริการ Kiosk',fields,async form=>{const data=Object.fromEntries(new FormData(form));data.active=form.active.checked;await kqApi('save-kiosk-template',{method:'POST',body:JSON.stringify(data)})});wrap.querySelector('[name=active]').checked=record.id?!!Number(record.active):true}
function kioskMenuTree(items){const roots=items.filter(item=>!item.parent_id),children=items.filter(item=>item.parent_id),known=new Set(roots.map(item=>String(item.id)));return roots.flatMap(root=>[root,...children.filter(item=>String(item.parent_id)===String(root.id))]).concat(children.filter(item=>!known.has(String(item.parent_id))))}
const kioskDayNames=['จ.','อ.','พ.','พฤ.','ศ.','ส.','อา.'];
function kioskMenuSchedule(record={}){let saved=[];try{saved=JSON.parse(record.schedule_json||'[]')}catch{}const legacyStart=record.start_time?.slice(0,5)||'00:00',legacyEnd=record.end_time?.slice(0,5)||'00:00';return Array.from({length:7},(_,index)=>{const weekday=index+1,day=saved.find(item=>+item.weekday===weekday);return{weekday,active:day?!!day.active:true,start_time:day?.start_time?.slice(0,5)||legacyStart,end_time:day?.end_time?.slice(0,5)||legacyEnd}})}
function kioskScheduleWeeks(record={}){let saved=[];try{saved=JSON.parse(record.schedule_json||'[]')}catch{}return [...new Set((saved.find(item=>Array.isArray(item.weeks))?.weeks||[]).map(Number).filter(week=>week>=1&&week<=5))].sort()}
function kioskScheduleFields(record){const weeks=kioskScheduleWeeks(record);return `<fieldset class="kiosk-schedule full"><legend>วันและเวลาแสดงปุ่ม</legend><p>เลือกวันที่ต้องการ และกำหนดเวลาแยกแต่ละวัน (เวลาเริ่มเท่ากับเวลาสิ้นสุด = แสดงตลอดวัน)</p>${kioskMenuSchedule(record).map((day,index)=>`<div class="kiosk-schedule-day"><label class="kiosk-day-toggle"><input type="checkbox" name="schedule_active_${day.weekday}" ${day.active?'checked':''}> ${kioskDayNames[index]}</label><label>เริ่ม<input type="time" name="schedule_start_${day.weekday}" value="${day.start_time}" required></label><label>สิ้นสุด<input type="time" name="schedule_end_${day.weekday}" value="${day.end_time}" required></label></div>`).join('')}<div class="kiosk-schedule-weeks"><strong>สัปดาห์ที่ของเดือน <small>ไม่เลือก = ทุกสัปดาห์</small></strong><div>${[1,2,3,4,5].map(week=>`<label><input type="checkbox" name="schedule_week_${week}" ${weeks.includes(week)?'checked':''}> สัปดาห์ที่ ${week}</label>`).join('')}</div></div></fieldset>`}
function kioskScheduleSummary(record){const schedule=kioskMenuSchedule(record),active=schedule.filter(day=>day.active),weeks=kioskScheduleWeeks(record),weekText=weeks.length?` · สัปดาห์ ${weeks.join(',')}`:' · ทุกสัปดาห์';if(!active.length)return'ไม่แสดง';const sameTime=active.every(day=>day.start_time===active[0].start_time&&day.end_time===active[0].end_time);if(sameTime){const days=active.length===7?'ทุกวัน':active.map(day=>kioskDayNames[day.weekday-1]).join(' '),time=active[0].start_time===active[0].end_time?'ตลอดวัน':`${active[0].start_time}–${active[0].end_time}`;return`${days} · ${time}${weekText}`}return active.map(day=>`${kioskDayNames[day.weekday-1]} ${day.start_time}–${day.end_time}`).join(', ')+weekText}
async function renderKioskMenu(templateId){
  kioskAdmin.selected=templateId;
  const result=await kioskApiGet('kiosk-menu-items',{template_id:templateId});
  kioskAdmin.menu=result.data;
  const template=kioskAdmin.templates.find(x=>+x.id===templateId);
  const area=document.getElementById('kioskMenuArea');
  const rows=kioskMenuTree(kioskAdmin.menu).map(x=>{
    const hasChildren=!x.parent_id&&kioskAdmin.menu.some(child=>String(child.parent_id)===String(x.id));
    const toggle=hasChildren?`<button type="button" class="kiosk-menu-toggle" data-menu-toggle="${x.id}" aria-expanded="false" aria-label="แสดงเมนูย่อยของ ${kioskEscape(x.label)}">›</button>`:'';
    return `<article class="kiosk-menu-row ${x.parent_id?'child hidden':''} ${Number(x.active)?'':'inactive-row'}"${x.parent_id?` data-menu-parent="${x.parent_id}"`:''}><i class="kiosk-menu-icon">${kioskEscape(x.icon||'Q')}</i><div><strong>${toggle}${x.parent_id?'↳ ':''}${kioskEscape(x.label)}</strong><small>${kioskEscape(x.subtitle||'')}</small></div><div><strong>${kioskEscape(x.service_name||x.department_name||'เมนูหมวดหมู่')}</strong><small>${x.parent_id?'เมนูย่อย':'เมนูหลัก'}</small></div><div class="kiosk-schedule-summary">${kioskEscape(kioskScheduleSummary(x))}</div>${kioskActive(x.active)}<button class="record-button" data-menu-edit="${x.id}">แก้ไข</button></article>`;
  }).join('');
  area.innerHTML=`<section class="admin-section"><div class="section-title"><div><h3>ปุ่มของ ${kioskEscape(template.name)}</h3><p>กดลูกศรหน้าเมนูหลักเพื่อแสดงหรือซ่อนเมนูย่อย</p></div><button class="mini-button" id="addKioskMenu">＋ เพิ่มปุ่ม</button></div></section><div class="kiosk-menu-list">${rows||'<div class="kiosk-empty">ยังไม่มีปุ่มสำหรับ Kiosk นี้</div>'}</div>`;
  document.getElementById('addKioskMenu').onclick=()=>openKioskMenuDialog({template_id:templateId});
  area.querySelectorAll('[data-menu-toggle]').forEach(button=>button.onclick=()=>{
    const expanded=button.getAttribute('aria-expanded')!=='true';
    button.setAttribute('aria-expanded',String(expanded));
    button.setAttribute('aria-label',`${expanded?'ซ่อน':'แสดง'}เมนูย่อย`);
    area.querySelectorAll(`[data-menu-parent="${button.dataset.menuToggle}"]`).forEach(row=>row.classList.toggle('hidden',!expanded));
  });
  area.querySelectorAll('[data-menu-edit]').forEach(b=>b.onclick=()=>openKioskMenuDialog(kioskAdmin.menu.find(x=>String(x.id)===b.dataset.menuEdit)));
}
function openKioskMenuDialog(record={}){
  const top=kioskAdmin.menu.filter(x=>!x.parent_id&&String(x.id)!==String(record.id));
  const fields=`<input type="hidden" name="id" value="${record.id||0}"><input type="hidden" name="template_id" value="${record.template_id||kioskAdmin.selected}"><label>ประเภทเมนู<select name="parent_id"><option value="">เมนูหลัก</option>${top.map(x=>`<option value="${x.id}" ${String(x.id)===String(record.parent_id)?'selected':''}>เมนูย่อยของ ${kioskEscape(x.label)}</option>`).join('')}</select></label><label>ลำดับ<input name="sort_order" type="number" min="0" value="${record.sort_order??0}"></label><label>ชื่อปุ่ม<input name="label" value="${kioskEscape(record.label||'')}" required></label><label>ไอคอน / อักษรนำเลขคิว<input name="icon" maxlength="4" value="${kioskEscape(record.icon||'Q')}" placeholder="เช่น A, ER หรือ ท"><small>ตัวอักษร/ตัวเลขจะใช้สร้างเลขคิว เช่น ER-001</small></label><label class="full">คำอธิบาย<input name="subtitle" value="${kioskEscape(record.subtitle||'')}"></label><label>แผนก<select name="department_id"><option value="">ไม่ผูกแผนก</option>${kioskAdmin.departments.map(x=>`<option value="${x.id}" ${String(x.id)===String(record.department_id)?'selected':''}>${kioskEscape(x.name)} · ${kioskEscape(x.branch_name)}</option>`).join('')}</select></label><label>บริการ<select name="service_id"><option value="">ทุกบริการในแผนก</option>${kioskAdmin.services.map(x=>`<option value="${x.id}" ${String(x.id)===String(record.service_id)?'selected':''}>${kioskEscape(x.name)} · ${kioskEscape(x.department_name)}</option>`).join('')}</select></label>${kioskScheduleFields(record)}`;
  const wrap=kioskDialog(record.id?'แก้ไขปุ่ม Kiosk':'เพิ่มปุ่ม Kiosk',fields,async form=>{
    const formData=new FormData(form),data=Object.fromEntries(formData);
    const weeks=[1,2,3,4,5].filter(week=>formData.has(`schedule_week_${week}`));data.schedule=Array.from({length:7},(_,index)=>{const weekday=index+1;return{weekday,active:formData.has(`schedule_active_${weekday}`),start_time:String(formData.get(`schedule_start_${weekday}`)||''),end_time:String(formData.get(`schedule_end_${weekday}`)||''),weeks}});
    Object.keys(data).filter(key=>key.startsWith('schedule_')).forEach(key=>delete data[key]);
    data.active=form.active.checked;
    await kqApi('save-kiosk-menu-item',{method:'POST',body:JSON.stringify(data)});
  });
  wrap.querySelector('[name=active]').checked=record.id?!!Number(record.active):true;
}
document.querySelectorAll('.nav-item[data-view="kiosks"]').forEach(node=>node.onclick=()=>{document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n===node));document.getElementById('dashboardView').classList.add('hidden');document.getElementById('genericView').classList.remove('hidden');document.getElementById('sidebar').classList.remove('open');kioskAdmin.selected=0;renderKioskAdmin().catch(error=>showToast(error.message))});
